#!/bin/bash
set -euo pipefail
WEB=/var/www/fusionpbx/app/agent_dashboard
B64_skykin_config_php=''
echo "${B64_skykin_config_php}" | base64 -d > /tmp/skykin_config.php
docker cp /tmp/skykin_config.php skykin-web:$WEB/skykin_config.php
B64_supervisor_php=''
echo "${B64_supervisor_php}" | base64 -d > /tmp/supervisor.php
docker cp /tmp/supervisor.php skykin-web:$WEB/supervisor.php
B64_index_php=''
echo "${B64_index_php}" | base64 -d > /tmp/index.php
docker cp /tmp/index.php skykin-web:$WEB/index.php
B64_data_php=''
echo "${B64_data_php}" | base64 -d > /tmp/data.php
docker cp /tmp/data.php skykin-web:$WEB/data.php
B64_reports_php=''
echo "${B64_reports_php}" | base64 -d > /tmp/reports.php
docker cp /tmp/reports.php skykin-web:$WEB/reports.php
docker exec skykin-web php -r 'opcache_reset();' 2>/dev/null || true
docker exec skykin-web php -r '
require "/var/www/fusionpbx/app/agent_dashboard/skykin_config.php";
$a=["direction"=>"inbound","billsec"=>45,"duration"=>50,"hangup_cause"=>"NORMAL_CLEARING","destination_number"=>"+251116198038","caller_id_number"=>"+251911111111","start_epoch"=>1000,"last_arg"=>"","cc_agent_bridged"=>""];
$b=["direction"=>"inbound","billsec"=>0,"duration"=>1,"hangup_cause"=>"CALL_REJECTED","destination_number"=>"+251116198037","caller_id_number"=>"+251922222222","start_epoch"=>2000,"last_arg"=>"","cc_agent_bridged"=>""];
$c=["direction"=>"inbound","billsec"=>65,"duration"=>70,"hangup_cause"=>"NORMAL_CLEARING","destination_number"=>"+251116198036","caller_id_number"=>"+251933333333","start_epoch"=>3000,"last_arg"=>"user/203@ahununu","cc_agent_bridged"=>"/203@ahununu"];
echo skykin_cdr_result_label($a)," ",skykin_cdr_result_label($b)," ",skykin_cdr_result_label($c),"\n";
'
echo DONE
